"""Generated by scripts/generate_fhir_datatypes.py from HL7's R4 JSON schema - do not edit by hand.

The 20 FHIR primitive types as constrained aliases. The patterns are HL7's own. A primitive
carries no `id`/`extension` here (the `_element` siblings are not modelled).
"""

from __future__ import annotations

from typing import Annotated

from pydantic import Field, StringConstraints

Base64Binary = Annotated[str, Field(description="A stream of bytes")]

Boolean = Annotated[bool, Field(description='Value of "true" or "false"')]

Canonical = Annotated[
    str,
    StringConstraints(pattern="^\\S*$"),
    Field(
        description="A URI that is a reference to a canonical URL on a FHIR resource"
    ),
]

Code = Annotated[
    str,
    StringConstraints(pattern="^[^\\s]+(\\s[^\\s]+)*$"),
    Field(
        description="A string which has at least one character and no leading or trailing whitespace and where there is no whitespace other than single spaces in the contents"
    ),
]

Date = Annotated[
    str,
    StringConstraints(
        pattern="^([0-9]([0-9]([0-9][1-9]|[1-9]0)|[1-9]00)|[1-9]000)(-(0[1-9]|1[0-2])(-(0[1-9]|[1-2][0-9]|3[0-1]))?)?$"
    ),
    Field(
        description="A date or partial date (e.g. just year or year + month). There is no time zone. The format is a union of the schema types gYear, gYearMonth and date.  Dates SHALL be valid dates."
    ),
]

DateTime = Annotated[
    str,
    StringConstraints(
        pattern="^([0-9]([0-9]([0-9][1-9]|[1-9]0)|[1-9]00)|[1-9]000)(-(0[1-9]|1[0-2])(-(0[1-9]|[1-2][0-9]|3[0-1])(T([01][0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?(Z|(\\+|-)((0[0-9]|1[0-3]):[0-5][0-9]|14:00)))?)?)?$"
    ),
    Field(
        description="A date, date-time or partial date (e.g. just year or year + month).  If hours and minutes are specified, a time zone SHALL be populated. The format is a union of the schema types gYear, gYearMonth, date and dateTime. Seconds must be provided due to schema type constraints but may be zero-filled and may be ignored.                 Dates SHALL be valid dates."
    ),
]

Decimal = Annotated[
    float, Field(description="A rational number with implicit precision")
]

Id = Annotated[
    str,
    StringConstraints(pattern="^[A-Za-z0-9\\-\\.]{1,64}$"),
    Field(
        description='Any combination of letters, numerals, "-" and ".", with a length limit of 64 characters.  (This might be an integer, an unprefixed OID, UUID or any other identifier pattern that meets these constraints.)  Ids are case-insensitive.'
    ),
]

Instant = Annotated[
    str,
    StringConstraints(
        pattern="^([0-9]([0-9]([0-9][1-9]|[1-9]0)|[1-9]00)|[1-9]000)-(0[1-9]|1[0-2])-(0[1-9]|[1-2][0-9]|3[0-1])T([01][0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?(Z|(\\+|-)((0[0-9]|1[0-3]):[0-5][0-9]|14:00))$"
    ),
    Field(description="An instant in time - known at least to the second"),
]

Integer = Annotated[int, Field(description="A whole number")]

Markdown = Annotated[
    str,
    Field(
        description="A string that may contain Github Flavored Markdown syntax for optional processing by a mark down presentation engine"
    ),
]

Oid = Annotated[
    str,
    StringConstraints(pattern="^urn:oid:[0-2](\\.(0|[1-9][0-9]*))+$"),
    Field(description="An OID represented as a URI"),
]

PositiveInt = Annotated[
    int, Field(ge=1, description="An integer with a value that is positive (e.g. >0)")
]

String = Annotated[str, Field(description="A sequence of Unicode characters")]

Time = Annotated[
    str,
    StringConstraints(
        pattern="^([01][0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?$"
    ),
    Field(description="A time during the day, with no date specified"),
]

UnsignedInt = Annotated[
    int,
    Field(ge=0, description="An integer with a value that is not negative (e.g. >= 0)"),
]

Uri = Annotated[
    str,
    StringConstraints(pattern="^\\S*$"),
    Field(description="String of characters used to identify a name or a resource"),
]

Url = Annotated[
    str,
    StringConstraints(pattern="^\\S*$"),
    Field(description="A URI that is a literal reference"),
]

Uuid = Annotated[
    str,
    StringConstraints(
        pattern="^urn:uuid:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$"
    ),
    Field(description="A UUID, represented as a URI"),
]

Xhtml = Annotated[str, Field(description="xhtml - escaped html (see specfication)")]
